                    r_from,r_to=a2,a
                    for rr in range(min(r_from,r_to),max(r_from,r_to)+1):
                        if (rr,cc) not in barcells and out[rr][cc]!=4:
                            out[rr][cc]=s
            if t=='v' and b0<=r<=b1:
                off=r-b0
                _,a2,r0,r1,_=other
                rr=r0+off
                if rr<=r1:
                    c_from,c_to=a2,c
                    for cc in range(min(c_from,c_to),max(c_from,c_to)+1):
                        if (rr,cc) not in barcells and out[rr][cc]!=4:
                            out[rr][cc]=s
    return out

