lib = '''import json
from collections import Counter, defaultdict


def find_bars_and_seeds(g):
    """Find the two parallel bars (runs >=2 of a non-bg color) and scattered seed cells of an ARC grid."""
    H, W = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    runs = []
    for r in range(H):
        c = 0
        while c < W:
            if g[r][c] != bg:
                c0 = c
                while c < W and g[r][c] == g[r][c0]:
                    c += 1
                if c - c0 >= 2:
                    runs.append(('h', r, c0, c - 1, g[r][c0]))
            else:
                c += 1
    for c in range(W):
        r = 0
        while r < H:
            if g[r][c] != bg:
                r0 = r
                while r < H and g[r][c] == g[r0][c]:
                    r += 1
                if r - r0 >= 2:
                    runs.append(('v', c, r0, r - 1, g[r0][c]))
            else:
                r += 1
    byc = defaultdict(list)
    for run in runs:
        byc[run[4]].append(run)
    bars = []
    for col, rs in byc.items():
        if len(rs) == 2 and all(x[0] == rs[0][0] for x in rs):
            bars = rs
    barcells = set()
    for t, a, b0, b1, _ in bars:
        if t == 'h':
            barcells |= {(a, c) for c in range(b0, b1 + 1)}
        else:
            barcells |= {(r, a) for r in range(b0, b1 + 1)}
    seeds = [(r, c, g[r][c]) for r in range(H) for c in range(W)
             if g[r][c] != bg and (r, c) not in barcells]
    return bg, bars, barcells, seeds


def fill_from_seeds(g, seeds, barcells, recolor_to=4):
    """Recolor seeds to `recolor_to` and extend each seed toward its containing bar."""
    out = [row[:] for row in g]
    for r, c, s in seeds:
        bg, bars, bc, sd = find_bars_and_seeds(g)
        for t, a, b0, b1, _ in bars:
            if t == 'h' and b0 <= c <= b1:
                step = 1 if a > r else -1
                rr = r + step
                while 0 <= rr < len(g) and (rr, c) not in bc:
                    out[rr][c] = s
                    rr += step
            if t == 'v' and b0 <= r <= b1:
                step = 1 if a > c else -1
                cc = c + step
                while 0 <= cc < len(g[0]) and (r, cc) not in bc:
                    out[r][cc] = s
                    cc += step
    for r, c, s in seeds:
        out[r][c] = recolor_to
    return out


def transplant_offsets(g, fills, seeds, recolor_to=4):
    """Copy each seed fill to the other bar at the same along-bar offset, filling the full extent between bars."""
    out = [row[:] for row in fills]
    bg, bars, bc, sd = find_bars_and_seeds(g)
    for r, c, s in seeds:
        for i, (t, a, b0, b1, _) in enumerate(bars):
            other = bars[1 - i]
            if t == 'h' and b0 <= c <= b1:
                off = c - b0
                _, a2, c0, c1, _ = other
                cc = c0 + off
                if cc <= c1:
                    for rr in range(min(a2, a), max(a2, a) + 1):
                        if (rr, cc) not in bc and out[rr][cc] != recolor_to:
                            out[rr][cc] = s
            if t == 'v' and b0 <= r <= b1:
                off = r - b0
                _, a2, r0, r1, _ = other
                rr = r0 + off
                if rr <= r1:
                    for cc in range(min(a2, a), max(a2, a) + 1):
                        if (rr, cc) not in bc and out[rr][cc] != recolor_to:
                            out[rr][cc] = s
    return out


def load_pairs(path):
    """Load demo pairs from a task json file."""
    data = json.load(open(path))
    if isinstance(data, dict):
        data = data.get('pairs', data)
    return [(p['input'], p['output']) for p in data]
